function describe(n, depth) {
  if (!n) return null;
  const info = {
    id: n.id, name: n.name, type: n.type,
    x: Math.round(n.x), y: Math.round(n.y),
    w: Math.round(n.width), h: Math.round(n.height)
  };
  if (n.fills !== figma.mixed && Array.isArray(n.fills)) info.fills = n.fills;
  if ('cornerRadius' in n && typeof n.cornerRadius === 'number') info.cornerRadius = n.cornerRadius;
  if (n.type === 'TEXT') {
    info.characters = n.characters;
    if (n.fontSize !== figma.mixed) info.fontSize = n.fontSize;
    if (n.fontName !== figma.mixed) info.fontName = n.fontName;
    if (n.fontWeight !== figma.mixed && typeof n.fontWeight !== 'symbol') info.fontWeight = n.fontWeight;
    if (Array.isArray(n.fills)) info.fills = n.fills;
  }
  if (depth > 0 && 'children' in n && n.children) {
    info.children = n.children.map(c => describe(c, depth - 1));
  }
  return info;
}
