function col(f){ if(!f) return "?"; if(f.type!=="SOLID") return f.type; const c=f.color||{}; return "rgb("+Math.round((c.r||0)*255)+","+Math.round((c.g||0)*255)+","+Math.round((c.b||0)*255)+")"; }
function dump(n, depth) {
  if (!n || depth > 3) return null;
  const o = {id:n.id, name:n.name, type:n.type, w:Math.round(n.width), h:Math.round(n.height)};
  try { if ("fills" in n && Array.isArray(n.fills)) o.fills = n.fills.map(col); } catch(e){ o.fills="err"; }
  try { if ("strokes" in n && Array.isArray(n.strokes) && n.strokes.length) o.strokes = n.strokes.map(col); } catch(e){}
  if (n.children && n.children.length) o.ch = n.children.map(c=>dump(c, depth+1));
  return o;
}
