function paintVectors(node, paint) {
  for (const v of node.findAll(x => x.type === "VECTOR")) {
    try {
      if (Array.isArray(v.strokes) && v.strokes.length) v.strokes = [paint];
      if (Array.isArray(v.fills) && v.fills.length) v.fills = [paint];
    } catch(e){ out.errs.push(v.id+":"+String(e)); }
  }
}
function ancestorsInclude(n, pred, depth) {
  let p = n.parent, d = 0;
  while (p && d < (depth||8)) { if (pred(p)) return true; p = p.parent; d++; }
  return false;
}

const icons = ws.findAll(n => n.type === "INSTANCE" && /^Icon_/.test(n.name));
