    ic.fills = [];
    const inHistory = ancestorsInclude(ic, p => p.name === "History button");
    const inCard = ancestorsInclude(ic, p => p.name === "Card / Balance");
    if (inHistory) paintVectors(ic, WHITE);
    else if (inCard) paintVectors(ic, ic.name === "Icon_Check_Badge" ? WHITE : BRAND);
