  try { o.cr = n.cornerRadius; } catch(e){}
  if (n.children) o.ch = n.children.map(c=>({id:c.id,name:c.name,type:c.type,fills:Array.isArray(c.fills)?c.fills.map(f=>f.type==="SOLID"?"rgb("+Math.round((f.color.r||0)*255)+","+Math.round((f.color.g||0)*255)+","+Math.round((f.color.b||0)*255)+")":f.type):"?", strokes:Array.isArray(c.strokes)?c.strokes.length:0}));
  return o;
}
