const jobs = [
 ["15:88", "Icon_Receive", WHITE],
 ["15:93", "Icon_Scan", WHITE],
 ["15:285", "Icon_Logout", RED],
];
for (const [pid, iconName, vecPaint] of jobs) {
  const parent = await figma.getNodeByIdAsync(pid);
  const ic = parent.children.find(c => c.type === "INSTANCE" && c.name === iconName);
