    if (Array.isArray(v.fills) && v.fills.length) v.fills = [vecPaint];
  }
  const vInfo = ic.findAll(x=>x.type==="VECTOR").map(v=>({s:Array.isArray(v.strokes)&&v.strokes.length?("rgb("+Math.round(v.strokes[0].color.r*255)+","+Math.round(v.strokes[0].color.g*255)+","+Math.round(v.strokes[0].color.b*255)+")"):"none", f:Array.isArray(v.fills)&&v.fills.length?"has":"none"}));
  out.steps.push(pid + " " + iconName + " cleared, vectors " + JSON.stringify(vInfo));
